inline void Require(bool v,const char* m){if(!v)throw std::invalid_argument(m);}
inline auto Q(Database& db,const std::string& s){auto r=db.QueryDatabase(s,false);Require(r.Success(),"Catalog upgrade SQL failed");return r;}
inline uint64_t N(const char* s){Require(s&&*s,"Missing upgrade number");std::string v=s;Require(v.find_first_not_of("0123456789")==std::string::npos,"Invalid upgrade number");return std::stoull(v);}
inline std::string S(Database& db,const std::string& s){return "'"+db.Escape(s)+"'";}
inline std::string Hex(const std::vector<uint8_t>& b){const char* h="0123456789abcdef";std::string s;for(auto c:b){s+=h[c>>4];s+=h[c&15];}return s;}
inline std::string Hash(const std::vector<uint8_t>& b){std::vector<uint8_t> out(32);Require(SHA256(b.data(),b.size(),out.data()),"Upgrade hash failed");return Hex(out);}
inline std::string Identity(const ContentBinding::Identity& v){return Hex({v.digest.begin(),v.digest.end()});}
