inline Catalog::Bundle After(const Plan& p){using namespace Detail;auto b=p.before;Require(b.provenance.origin==Catalog::Origin::Experimental&&b.revision&&b.revision<UINT64_MAX&&ContentBinding::Detail::Key(b.key)&&p.request_key.size()&&p.request_key.size()<=128&&ContentBinding::Detail::Hash(p.sha256)&&p.review.rfind("EXPERIMENTAL:",0)==0&&p.review.size()<=255,"Unreviewed upgrade plan");Require(p.crate.id==174&&p.crate.type==7&&p.crate.max_items&&p.crate.max_non_estate_items<=p.crate.max_items&&!p.crate.area_id&&!p.crate.zone_id&&!p.crate.dynamic_zone_id&&!p.crate.purchase_scheme&&!p.crate.upkeep_scheme&&!p.crate.max_children&&p.crate.children.empty(),"Only reviewed non-zoned crate174 may be added");Require(std::none_of(b.definitions.begin(),b.definitions.end(),[](const auto& d){return d.id==174;}),"Crate already belongs to another transition");std::set<uint32_t> seen;for(auto id:p.plots){Require(seen.insert(id).second,"Duplicate upgrade plot");auto d=std::find_if(b.definitions.begin(),b.definitions.end(),[&](const auto& v){return v.id==id;});Require(d!=b.definitions.end()&&d->type==4&&d->max_children==1&&std::find(d->children.begin(),d->children.end(),174)==d->children.end(),"Only existing one-house personal plots may add crate");d->children.push_back(174);d->max_children=2;}Require(!seen.empty(),"No upgrade plot");b.definitions.push_back(p.crate);++b.revision;b.provenance={Catalog::Origin::Experimental,p.review,p.sha256,20130510};Catalog::Validate(b);return b;}
