  Route physical{uint32_t(N(r[17])),uint8_t(N(r[18])),uint16_t(N(r[19]))};auto before=ContentBinding::Current(db,after.key,plan.before,N(r[1]),physical,row.values.item_id,route),next=ContentBinding::Current(db,after.key,after,N(r[1]),physical,row.values.item_id,route);Require(ContentBinding::Same(*stored,before)&&before.version==next.version,"Pre-upgrade fingerprint mismatch");changes.push_back({uint32_t(N(r[0])),before.version,Identity(before),Identity(next)});
