 CustodyCodec::Bytes witness;for(const auto& c:changes){CustodyCodec::W(witness,c.native,4);CustodyCodec::W(witness,c.version,4);CustodyCodec::S(witness,c.before);CustodyCodec::S(witness,c.after);}if(!write)return {true,false,uint64_t(changes.size()),interiors,{}};
