 auto policies=Q(db,"SELECT definition_id,definitions_sha256,regions_sha256,catalog_revision,policy_revision FROM housing_native_plot_purchase_policies WHERE catalog_key="+key+" FOR UPDATE");for(auto row=policies.begin();row!=policies.end();++row){Require(row[0]&&row[1]&&row[2]&&N(row[3])==plan.before.revision&&std::string(row[1])==Hash(old_bytes)&&std::string(row[2])==Hash(regions)&&N(row[4])<UINT64_MAX,"Purchase policy upgrade mismatch");auto policy=Q(db,"UPDATE housing_native_plot_purchase_policies SET catalog_revision="+to+",definitions_sha256='"+Hash(new_bytes)+"',policy_revision=policy_revision+1 WHERE catalog_key="+key+" AND definition_id="+std::string(row[0])+" AND catalog_revision="+from);Require(policy.RowsAffected()==1,"Purchase policy CAS failed");}
